/** Text as Markdown shows it: `<` and `>` outside code spans are no HTML. */
const literal = text =>
  String(text)
    .split(/(`[^`]*`)/)
    .map((part, i) =>
      i % 2 ? part : part.replaceAll('<', '&lt;').replaceAll('>', '&gt;'),
    )
    .join('');

const cell = (text = '') =>
  literal(text).replace(/\s+/g, ' ').replaceAll('|', '\\|').trim();

/** Prose without the design records' references, which explain why rather than what. */
export const plain = text =>
  text
    .replace(
      /\s*\((?:[^()]|\([^()]*\))*\b(?:decisions?|reviews?|roadmap|findings?|D\d+|V10)\b(?:[^()]|\([^()]*\))*\)/g,
      '',
    )
    // A KDoc link `[Name]` reads as code, outside code spans only.
    .split(/(`[^`]*`)/)
    .map((part, i) => (i % 2 ? part : part.replace(/\[([\w.]+)\]/g, '`$1`')))
    .join('')
    .replace(/\s+([,.;:])/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();

/** The first sentence of a text. */
export const firstSentence = text => {
  const match = /^.*?[.!?](?=\s+[A-Z`(\[]|$)/s.exec(text);
  return (match ? match[0] : text).trim();
};

const page = (locale, title, description, sources, body) =>
  [
    '---',
    `title: ${title}`,
    `description: "${description}"`,
    '---',
    '',
    WORDS[locale].generated(sources),
    '',
    `# ${title}`,
    '',
    ...body,
  ].join('\n') + '\n';

// Configuration

const javaType = (type = '') =>
  type
    .replace(/\b(?:java\.(?:lang|time|util)|kotlin)\./g, '')
    .replace(/\bme\.ahoo\.wow\.[\w.]+\.(\w+(?:\$\w+)*)/g, (_, name) =>
      name.split('$').at(-1),
    );

const defaultOf = value => {
  if (value === undefined) return '';
  const text = Array.isArray(value) ? value.join(', ') : String(value);
  return text === '' ? '`""`' : `\`${text}\``;
};

/** The configuration's groups, each with its properties: `[{ name, description, properties }]`. */
export function configurationGroups(metadata) {
  const groups = metadata.groups.map(group => ({ ...group, properties: [] }));
  for (const property of metadata.properties) {
    const owner =
      groups.find(
        group =>
          group.type === property.sourceType &&
          property.name.startsWith(`${group.name}.`),
      ) ??
      groups
        .filter(group => property.name.startsWith(`${group.name}.`))
        .sort((a, b) => b.name.length - a.name.length)[0];
    owner?.properties.push(property);
  }
  return groups
    .filter(group => group.properties.length > 0)
    .sort((a, b) => a.name.localeCompare(b.name))
    .map(group => ({
      ...group,
      properties: group.properties.sort((a, b) => a.name.localeCompare(b.name)),
    }));
}

export function configurationPage(locale, metadata) {
  const words = WORDS[locale].config;
  const groups = configurationGroups(metadata);
  const body = [words.intro(metadata.properties.length), ''];
  for (const group of groups) {
    body.push(`## \`${group.name}\``, '');
    // The root group's description is an index of the others.
    if (group.description && group.name !== 'wow')
      body.push(literal(plain(group.description)), '');
    body.push(words.head, '| --- | --- | --- | --- |');
    for (const property of group.properties) {
      body.push(
        `| \`${property.name}\` | ${cell(`\`${javaType(property.type)}\``)} | ${cell(defaultOf(property.defaultValue))} | ${cell(plain(property.description ?? ''))} |`,
      );
    }
    body.push('');
  }
  return page(locale, words.title, words.description, METADATA, body);
}

// Error codes

const kotlinString = literal =>
  [...literal.matchAll(/"((?:[^"\\]|\\.)*)"/g)]
    .map(match => match[1].replace(/\\(.)/g, '$1'))
    .join('');

/** The framework's codes from FrameworkErrors.kt: `[{ code, status, description }]`. */
export function frameworkErrors(source) {
  const constants = Object.fromEntries(
    [...source.matchAll(/const val (\w+): String = "([^"]+)"/g)].map(match => [
      match[1],
      match[2],
    ]),
  );
  const all = source.slice(source.indexOf('val ALL'));
  return [
    ...all.matchAll(
      /ErrorManifest\(\s*(\w+),\s*(\d+),\s*((?:"(?:[^"\\]|\\.)*"\s*\+?\s*)+),?\s*\)/g,
    ),
  ].map(match => ({
    code: constants[match[1]],
    status: Number(match[2]),
    description: kotlinString(match[3]),
  }));
}

/** The query request codes from QueryErrorCodes.kt, each with the comment of its group: `[{ code, group }]`. */
export function queryErrorCodes(source) {
  const codes = [];
  let group = '';
  let comment = [];
  for (const line of source
    .slice(source.indexOf('object QueryErrorCodes'))
    .split('\n')) {
    const text = line.trim();
    if (text.startsWith('//')) {
      comment.push(text.replace(/^\/\/\s?/, ''));
      continue;
    }
    if (comment.length) {
      group = plain(firstSentence(comment.join(' ')).replace(/;.*$/, '.'));
      comment = [];
    }
    const constant = /^const val \w+ = "(\w+)"/.exec(text);
    if (constant) codes.push({ code: constant[1], group });
  }
  return codes;
}

export function errorCodesPage(locale, framework, query) {
  const words = WORDS[locale].errors;
  const body = [
    words.intro,
    '',
    `## ${words.framework}`,
    '',
    words.head,
    '| --- | --- | --- |',
    ...framework.map(
      ({ code, status, description }) =>
        `| \`${code}\` | ${status} | ${cell(description)} |`,
    ),
    '',
    `## ${words.query}`,
    '',
    words.queryIntro,
    '',
    words.queryHead,
    '| --- | --- |',
    ...query.map(({ code, group }) => `| \`${code}\` | ${cell(group)} |`),
    '',
  ];
  return page(
    locale,
    words.title,
    words.description,
    `${FRAMEWORK_ERRORS}, ${QUERY_ERROR_CODES}`,
    body,
  );
}

// Annotations

/** The parts of a parameter list, split at its top-level commas. */
const topLevel = text => {
  const parts = [''];
  let depth = 0;
  for (const char of text) {
    if ('([{<'.includes(char)) depth++;
    if (')]}>'.includes(char)) depth--;
    if (char === ',' && depth === 0) parts.push('');
    else parts[parts.length - 1] += char;
  }
  return parts.filter(part => part.trim());
};

/** The annotation a Kotlin source declares, or undefined: `{ name, kdoc, targets, parameters }`. */
export function annotationOf(source) {
  const declaration =
    /\n((?:@[\w.]+(?:\([^)]*\))?\s*\n)*)annotation class (\w+)(?:\s*\(([\s\S]*?)\n\))?/.exec(
      source,
    );
  if (!declaration) return undefined;
  const before = source.slice(0, declaration.index);
  const kdoc = /\/\*\*([\s\S]*?)\*\/\s*$/.exec(before)?.[1] ?? '';
  const text = kdoc
    .split('\n')
    .map(line => line.replace(/^\s*\* ?/, ''))
    .join('\n');
  // The prose before the first code block, tag or list.
  const summary = text
    .split(/\n\s*\n|\n```|\n@\w|\n- /)[0]
    .replace(/\s+/g, ' ')
    .trim();
  const targets = [
    ...(/@Target\(([^)]*)\)/.exec(declaration[1])?.[1] ?? '').matchAll(
      /AnnotationTarget\.(\w+)/g,
    ),
  ].map(match => match[1]);
  const parameters = topLevel(declaration[3] ?? '')
    .map(part =>
      part
        .replace(/\/\/.*$/gm, '')
        .replace(/\s+/g, ' ')
        .trim(),
    )
    .map(part => /^val (\w+):\s*(.+?)(?:\s*=\s*(.+))?$/.exec(part))
    .filter(Boolean)
    .map(match => ({
      name: match[1],
      type: match[2].trim(),
      default: match[3]
        ?.trim()
        .replace(/\[\s+/g, '[')
        .replace(/,\s*]$/, ']'),
    }));
  return { name: declaration[2], summary, targets, parameters };
}

export function annotationsPage(locale, annotations) {
  const words = WORDS[locale].annotations;
  const body = [words.intro, ''];
  for (const { file, annotation } of annotations) {
    body.push(`## \`@${annotation.name}\``, '');
    body.push(
      `[${annotation.name}](${SOURCE}${ANNOTATIONS}/${file}): ${literal(plain(firstSentence(annotation.summary)))}`,
      '',
    );
    body.push(
      `- ${words.targets}: ${annotation.targets.map(target => `\`${target}\``).join(', ') || '—'}`,
    );
    body.push(
      `- ${words.parameters}: ${
        annotation.parameters
          .map(
            ({ name, type, default: value }) =>
              `\`${name}: ${type}${value === undefined ? '' : ` = ${value}`}\``,
          )
          .join(', ') || words.none
      }`,
      '',
    );
  }
  return page(locale, words.title, words.description, ANNOTATIONS, body);
}

/** Every generated page: `{ path: text }`, read from `root`. */
export function referencePages(root = ROOT) {
  const read = path => readFileSync(join(root, path), 'utf8');
  const metadata = JSON.parse(read(METADATA));
  const framework = frameworkErrors(read(FRAMEWORK_ERRORS));
  const snapshot = JSON.parse(read(FRAMEWORK_ERRORS_SNAPSHOT));
  const parsed = framework
    .map(({ code, status }) => `${code} ${status}`)
    .join('\n');
  const expected = snapshot
    .map(({ code, status }) => `${code} ${status}`)
    .join('\n');
  if (parsed !== expected)
    throw new Error(
      `${FRAMEWORK_ERRORS}: the codes read from its ALL table differ from ${FRAMEWORK_ERRORS_SNAPSHOT}`,
    );
  const query = queryErrorCodes(read(QUERY_ERROR_CODES));
  const annotations = readdirSync(join(root, ANNOTATIONS))
    .filter(file => file.endsWith('.kt'))
    .sort()
    .map(file => ({
      file,
      annotation: annotationOf(read(`${ANNOTATIONS}/${file}`)),
    }))
    // The API levels are not part of the programming model.
    .filter(
      ({ annotation }) =>
        annotation &&
        !/^(?:InternalWowApi|ExperimentalWowApi|WowSpi)$/.test(annotation.name),
    );
  const pages = {};
  for (const locale of Object.keys(WORDS)) {
    const dir = `documentation/docs/${locale}/reference`;
    pages[`${dir}/configuration.md`] = configurationPage(locale, metadata);
    pages[`${dir}/error-codes.md`] = errorCodesPage(locale, framework, query);
    pages[`${dir}/annotations.md`] = annotationsPage(locale, annotations);
  }
  return pages;
}

/** The sources each generated page is read from, by its file name. */
export const SOURCES = {
  'configuration.md': [METADATA],
  'error-codes.md': [
    FRAMEWORK_ERRORS,
    FRAMEWORK_ERRORS_SNAPSHOT,
    QUERY_ERROR_CODES,
  ],
  'annotations.md': [`${ANNOTATIONS}/`],
};

/** What a check that found `stale` pages says: the pages, their sources, and the one step that fixes them. */
export function staleMessage(stale) {
  const sources = [
    ...new Set(stale.flatMap(path => SOURCES[path.split('/').at(-1)] ?? [])),
  ];
  return [
    'The generated reference pages are not what their sources give:',
    ...stale.map(path => `  ${path}`),
    `They are generated from: ${sources.join(', ')}.`,
    'Fix: run `pnpm docs:reference` (or `node .github/scripts/docs-reference.mjs --write`) and commit those pages',
    'with the change to their sources.',
  ].join('\n');
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  const pages = referencePages();
  const write = process.argv.includes('--write');
  const stale = [];
  for (const [path, text] of Object.entries(pages)) {
    let current;
    try {
      current = readFileSync(join(ROOT, path), 'utf8');
    } catch {
      current = undefined;
    }
    if (current === text) continue;
    stale.push(path);
    if (write) writeFileSync(join(ROOT, path), text);
  }
  if (write) {
    for (const path of stale) console.log(`Wrote ${path}`);
    console.log(
      stale.length
        ? `Commit ${stale.length === 1 ? 'the page' : `the ${stale.length} pages`} above.`
        : 'The generated reference pages were up to date.',
    );
  } else if (stale.length > 0) {
    console.error(staleMessage(stale));
    process.exit(1);
  } else {
    console.log(
      `The generated reference pages are up to date (${Object.keys(pages).length} pages)`,
    );
  }
}
